import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) b = readByte();
            if (b == -1) return -1;
            long val = 0;
            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return val;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Line {
        long a, b;
        Line(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Meal {
        long a, b;
        Meal(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    // Exponenciação rápida modular
    static long power(long base, long exp) {
        long res = 1 % MOD;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    // Inverso modular via Pequeno Teorema de Fermat
    static long modInverse(long n) {
        return power(n, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        long K = fs.nextLong();

        long[] a_spell = new long[N];
        for (int i = 0; i < N; i++) a_spell[i] = fs.nextLong();
        long[] b_spell = new long[N];
        for (int i = 0; i < N; i++) b_spell[i] = fs.nextLong();

        long[] a_meal = new long[M];
        for (int i = 0; i < M; i++) a_meal[i] = fs.nextLong();
        long[] b_meal = new long[M];
        for (int i = 0; i < M; i++) b_meal[i] = fs.nextLong();

        int Q = fs.nextInt();
        long[] queries = new long[Q];
        for (int i = 0; i < Q; i++) queries[i] = fs.nextLong();

        // 1. Processar Refeições (Meals)
        Meal[] meals = new Meal[M];
        for (int i = 0; i < M; i++) {
            meals[i] = new Meal(a_meal[i], b_meal[i]);
        }

        // Ordenar refeições pelo Exchange Argument:
        // i vem antes de j se b_i * (a_j - 1) > b_j * (a_i - 1)
        Arrays.sort(meals, (m1, m2) -> {
            long v1 = m1.b * (m2.a - 1);
            long v2 = m2.b * (m1.a - 1);
            if (v1 != v2) {
                return Long.compare(v2, v1); // decrescente
            }
            return 0;
        });

        // Compor as transformações de todas as refeições
        long A_meals = 1;
        long B_meals = 0;
        for (int i = 0; i < M; i++) {
            long a_i = meals[i].a % MOD;
            long b_i = meals[i].b % MOD;
            A_meals = (A_meals * a_i) % MOD;
            B_meals = (B_meals * a_i + b_i) % MOD;
        }

        // 2. Encontrar o feitiço final dominante F* = (A_star, B_star)
        long A_star = -1;
        long B_star = -1;
        for (int i = 0; i < N; i++) {
            if (a_spell[i] > A_star) {
                A_star = a_spell[i];
                B_star = b_spell[i];
            } else if (a_spell[i] == A_star) {
                if (b_spell[i] > B_star) {
                    B_star = b_spell[i];
                }
            }
        }

        // 3. Construir o Upper Convex Hull das retas dos feitiços
        Line[] lines = new Line[N];
        for (int i = 0; i < N; i++) {
            lines[i] = new Line(a_spell[i], b_spell[i]);
        }

        Arrays.sort(lines, (l1, l2) -> {
            if (l1.a != l2.a) return Long.compare(l1.a, l2.a);
            return Long.compare(l1.b, l2.b);
        });

        // Filtrar linhas com mesma inclinação mantendo apenas o maior b
        List<Line> filtered = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            if (i + 1 < N && lines[i].a == lines[i + 1].a) continue;
            filtered.add(lines[i]);
        }

        // Construir envoltória
        Line[] hull = new Line[filtered.size()];
        int hullSize = 0;
        for (Line l : filtered) {
            while (hullSize >= 2) {
                Line l1 = hull[hullSize - 2];
                Line l2 = hull[hullSize - 1];
                // Interseção l1 e l2 vs l2 e l:
                // (l1.b - l2.b) / (l2.a - l1.a) >= (l2.b - l.b) / (l.a - l2.a)
                // Usando produto cruzado com BigInteger se necessário, mas cabe em double ou BigInteger
                long num1 = l1.b - l2.b;
                long den1 = l2.a - l1.a;
                long num2 = l2.b - l.b;
                long den2 = l.a - l2.a;

                // num1 * den2 >= num2 * den1
                // Ambos os lados são positivos e <= 10^18, cabem em double para estimativa segura
                // ou multiplicação exata:
                if ((double) num1 * den2 >= (double) num2 * den1) {
                    hullSize--;
                } else {
                    break;
                }
            }
            hull[hullSize++] = l;
        }

        // Pré-computação de potências para F* repetido (K - 1) vezes
        long mult_factor = 1;
        long add_factor = 0;
        if (K >= 1) {
            long k_rem = K - 1;
            mult_factor = power(A_star, k_rem);
            if (A_star == 1) {
                add_factor = ((k_rem % MOD) * (B_star % MOD)) % MOD;
            } else {
                long num = (mult_factor - 1 + MOD) % MOD;
                long den = modInverse((A_star - 1) % MOD);
                long geom_sum = (num * den) % MOD;
                add_factor = ((B_star % MOD) * geom_sum) % MOD;
            }
        }

        // 4. Responder às Q consultas
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        for (int q = 0; q < Q; q++) {
            long x = queries[q];

            long v_final;
            if (K == 0) {
                v_final = x % MOD;
            } else {
                // Encontrar o melhor feitiço para o 1º passo usando o CHT
                int low = 0, high = hullSize - 1;
                while (low < high) {
                    int mid = (low + high) / 2;
                    long val1 = hull[mid].a * x + hull[mid].b;
                    long val2 = hull[mid + 1].a * x + hull[mid + 1].b;
                    if (val1 <= val2) {
                        low = mid + 1;
                    } else {
                        high = mid;
                    }
                }

                Line bestLine = hull[low];
                long y_step1 = ( (bestLine.a % MOD) * (x % MOD) + (bestLine.b % MOD) ) % MOD;

                // Aplicar F* exatamente (K - 1) vezes sobre y_step1
                v_final = ( (y_step1 * mult_factor) % MOD + add_factor ) % MOD;
            }

            // Aplicar as refeições sobre v_final
            long ans = ( (A_meals * v_final) % MOD + B_meals ) % MOD;
            out.println(ans);
        }

        out.flush();
    }
}
